import{_ as e,o as t,c as d,ag as i}from"./chunks/framework.Dx86EdC1.js";const h=JSON.parse('{"title":"Wizard Instalasi Web","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengembang/wizard-instalasi.md","filePath":"panduan-pengembang/wizard-instalasi.md","lastUpdated":1791382762000}'),s={name:"panduan-pengembang/wizard-instalasi.md"};function n(o,a,l,r,c,p){return t(),d("div",null,[...a[0]||(a[0]=[i('<h1 id="wizard-instalasi-web" tabindex="-1">Wizard Instalasi Web <a class="header-anchor" href="#wizard-instalasi-web" aria-label="Permalink to &quot;Wizard Instalasi Web&quot;">​</a></h1><p>SiDesa memiliki wizard instalasi berbasis peramban yang terinspirasi dari WordPress Installer. Wizard ini aktif selama berkas kunci <code>storage/installed</code> <strong>belum ada</strong> — begitu terbentuk, seluruh rute diarahkan ke halaman utama (<code>RedirectIfNotInstalled</code>).</p><h2 id="akses" tabindex="-1">Akses <a class="header-anchor" href="#akses" aria-label="Permalink to &quot;Akses&quot;">​</a></h2><p>Setelah <code>composer install</code> dan <code>.env</code> tersedia, buka:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8000/install</span></span></code></pre></div><h2 id="alur-wizard" tabindex="-1">Alur Wizard <a class="header-anchor" href="#alur-wizard" aria-label="Permalink to &quot;Alur Wizard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tahap</th><th>Rute</th><th>Fungsi</th></tr></thead><tbody><tr><td>1. Pemeriksaan</td><td><code>/install</code></td><td>Cek versi PHP (min. <code>8.1.0</code>), ekstensi wajib, dan kesiapan direktori <code>storage/</code> + <code>bootstrap/cache</code> (lihat <code>config/installer.php</code>).</td></tr><tr><td>2. Database</td><td><code>/install/database</code></td><td>Form kredensial DB + tombol uji koneksi (<code>testDatabaseConnection</code>).</td></tr><tr><td>3. Setup Desa</td><td><code>/install/setup</code></td><td>Identitas desa, hierarki wilayah (Provinsi → Kabupaten → Kecamatan → Desa) via API Wilayah Kemendagri, akun Super Administrator utama, zona waktu (WIB/WITA/WIT dengan deteksi otomatis provinsi), alamat lengkap kantor desa, kode pos, telepon/WA, email resmi desa, serta opsi muat data contoh/demo.</td></tr><tr><td>4. Proses</td><td><code>/install/process</code></td><td>Menulis <code>.env</code> (<code>updateEnvironment</code> termasuk <code>APP_TIMEZONE</code>), <code>key:generate</code>, <code>migrate</code>, lalu menjalankan seeder inti: <code>RoleAndPermissionSeeder</code>, <code>SettingSeeder</code>, <code>LetterTemplateSeeder</code>, <code>MenuSeeder</code>.</td></tr><tr><td>5. Selesai</td><td><code>/install/completed</code></td><td>Menulis berkas kunci <code>storage/installed</code> berisi metadata instalasi dan versi aplikasi (<code>app_version</code>).</td></tr></tbody></table><p>Opsional pada tahap setup, wizard juga menjalankan seeder data contoh (<code>ResidentAndFamilySeeder</code>, <code>ContentSeeder</code>, <code>VillageBudgetAndMapSeeder</code>, <code>PpidSeeder</code>).</p><h2 id="reset-instal-ulang" tabindex="-1">Reset / Instal Ulang <a class="header-anchor" href="#reset-instal-ulang" aria-label="Permalink to &quot;Reset / Instal Ulang&quot;">​</a></h2><p>Hapus berkas kunci untuk mengaktifkan kembali wizard:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storage/installed</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Hati-hati</p><p>Wizard akan menimpa nilai <code>DB_*</code> pada <code>.env</code> dengan input form. Jalankan hanya di lingkungan yang Anda kendalikan penuh.</p></div><h2 id="mode-simulasi-testing" tabindex="-1">Mode Simulasi (Testing) <a class="header-anchor" href="#mode-simulasi-testing" aria-label="Permalink to &quot;Mode Simulasi (Testing)&quot;">​</a></h2><p><code>config/installer.php</code> menyediakan flag <code>simulate_uninstalled</code> untuk memaksa aplikasi berpura-pura belum terpasang — dipakai oleh test <code>tests/Feature/InstallerWorkflowTest.php</code>.</p>',14)])])}const k=e(s,[["render",n]]);export{h as __pageData,k as default};
